<template>
	<div class="flex h-screen items-center justify-center bg-gray-100 relative">
		<div class="absolute top-4 left-4">
			<BrandLogo />
		</div>

		<div class="h-screen flex items-center justify-center overflow-hidden">
			<div
				class="w-[80%] h-[80vh] flex gap-4 items-center justify-center"
				:class="{
					'flex-col': isVerticalScreen || !show_qr_camera,
					'flex-row': show_qr_camera && !isVerticalScreen,
				}"
			>
				<div
					:class="[
						'relative bg-white p-6 rounded-lg shadow-lg border border-gray-300 flex flex-col justify-center w-[800px] min-h-[600px]',
						show_qr_camera && !isVerticalScreen ? 'w-1/2 max-h-[600px]' : 'max-h-[600px]'
					]"
				>
					<h1 class="text-3xl font-bold text-center">Check In</h1>
					<div class="flex flex-col items-center gap-4 py-10">
						<FeatherIcon :name="'log-in'"
							class="w-[300px] h-[150px] object-contain rounded-md" />
					</div>

					<div class="flex justify-center items-center gap-2 py-4">
						<input
							type="text"
							v-model="patient_id"
							:placeholder="'Enter Mobile Number / QR ID'"
							class="px-4 py-2 border border-gray-300 rounded-lg w-[350px]"
						/>
						<Button
							@click="handleButtonClick"
							class="px-4 py-2 transition-all"
							:variant="'solid'"
							:ref_for="true"
							theme="gray"
							size="lg"
						>
							Checkin
						</Button>
						<Button v-if="!show_qr_camera"
							@click="openQRScanner"
							class="px-4 py-2"
							:variant="'subtle'"
							:ref_for="true"
							theme="gray"
							size="lg"
						>
							Scan QR
						</Button>
					</div>
				</div>
				<div v-if="show_qr_camera"
					:class="'bg-white p-6 rounded-lg shadow-lg border border-gray-300 flex flex-col items center justify-center w-[800px] min-h-[600px] w-1/2 max-h-[600px]'"
				>
					<h1 class="text-2xl py-2 text-center font-bold">Scan Your QR Code</h1>
					<div class="flex-grow rounded-lg overflow-hidden">
						<QrcodeStream
							:key="scannerKey"
							:constraints="selectedConstraints"
							@error="onError"
							@detect="onDetect"
							@camera-on="onCameraReady"
							class="w-full h-full rounded-lg"
						/>
					</div>
					<div v-if="error" class="text-red-500 text-sm mb-4 py-2">
						<ErrorMessage :message="error" />
					</div>
				</div>
			</div>
		</div>
	</div>
	<Footer />

	<Dialog :options="{
		title: `${dialog_title}`,
		message: `${dialog_message}`,
		size: 'xl',
		icon: {
			name: 'check',
			appearance: 'success',
		},
		actions: [
			{
				label: 'OK',
				variant: 'solid',
				onClick: () => {
					success_dialog = false;
					patient_id = '';
				}
			},
		],
	}" v-model="success_dialog" />

	<Dialog :options="{
		title: `${dialog_title}`,
		message: `${dialog_message}`,
		size: 'xl',
		icon: {
			name: 'alert-circle',
			appearance: 'warning',
		},
		actions: [
			{
				label: 'OK',
				variant: 'solid',
				onClick: () => {
					onCheckin();
				}
			},
		],
	}" v-model="route_dialog" />

	<Dialog :options="{
		title: `${dialog_title}`,
		message: `${dialog_message}`,
		size: 'xl',
		icon: {
			name: 'alert-triangle',
			appearance: 'warning',
		},
		actions: [
			{
				label: 'OK',
				variant: 'solid',
				onClick: () => {
					alert_dialog = false;
					patient_id = '';
				}
			},
		],
	}" v-model="alert_dialog" />

	<Dialog v-model="dialogPatient">
		<template #body-title>
			<h3>Select a Patient</h3>
		</template>
		<template #body-content>
			<div v-if="patientList.length > 0">
				<ul class="space-y-2">
					<li v-for="(patient, index) in patientList" :key="index"
						class="p-2 border rounded-lg flex items-center space-x-4 cursor-pointer"
						:class="{ 'bg-gray-200': selected_patient === patient.name }"
						@click="selectPatient(patient.name)">
						<div>
							<strong>{{ patient.patient_name }}</strong>
							<p class="text-sm text-gray-600">ID: {{ patient.name }}</p>
						</div>
					</li>
				</ul>
			</div>
			<div v-else>
				<p>No patients found.</p>
			</div>
		</template>
		<template #actions>
			<Button variant="solid" :disabled="!selected_patient" @click="confirmSelection">
				Confirm
			</Button>
			<Button class="ml-2" @click="dialogPatient = false">
				Close
			</Button>
		</template>
	</Dialog>
	<Dialog v-model="dialogAppointment">
		<template #body-title>
			<h3>Select your Appointment</h3>
		</template>
		<template #body-content>
			<div v-if="appointmentList.length > 0">
				<ul class="space-y-2">
					<li v-for="(app, index) in appointmentList" :key="index"
						class="p-2 border rounded-lg flex items-center space-x-4 cursor-pointer"
						:class="{ 'bg-gray-200': selectedAppointment === app.name }" @click="selectAppointment(app.name)">
						<div>
							<strong>{{ app.practitioner_name }}</strong>
							<p class="text-sm text-gray-600">ID: {{ app.name }} Time: {{ app.appointment_time }}</p>
						</div>
					</li>
				</ul>
			</div>
			<div v-else>
				<p>No Appointments found.</p>
			</div>
		</template>
		<template #actions>
			<Button variant="solid" :disabled="!selectedAppointment" @click="confirmAppSelection">
				Confirm
			</Button>
			<Button class="ml-2" @click="dialogAppointment = false">
				Close
			</Button>
		</template>
	</Dialog>
	<Dialog v-model="qr_dialog" :options="{
		title: dialog_title,
		message: dialog_message,
		size: 'xl',
		icon: {
			name: 'grid',
			appearance: 'info',
		},
		actions: [
			{
				label: 'Close',
				variant: 'subtle',
				onClick: () => {
					qr_dialog = false;
				},
			},
		],
	}">
		<template #body-content>
			<div class="flex flex-col space-y-4">
				<div class="h-[400px] rounded-lg shadow-lg">
					<qrcode-stream
						:constraints="selectedConstraints"
						@error="onError"
						@detect="onDetect"
						@camera-on="onCameraReady"
						class="w-full h-full rounded-lg shadow-lg"
					/>
				</div>
			</div>
		</template>
	</Dialog>

	<!-- patient profile completeion before booking -->
	<Dialog
		v-model="complete_profile_dialog"
		:options="{
			size: '3xl',
		}"
		>
		<template #body-title>
			<h3 class="font-bold">Complete Patient Profile</h3>
		</template>
		<template #body-content>
			<!-- Patient Demography Section -->
			<div class="mb-4">
				<h4 class="py-2 font-semibold text-lg mb-2">Patient Demography</h4>
				<div class="grid grid-cols-3 gap-2">
					<!-- Left Side Fields -->
					<div class="py-1 w-full">
						<FormControl label="First Name" v-model="form_firstName" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_firstName" :message="errors.form_firstName" />
					</div>
					<div class="py-1 w-full">
						<FormControl label="Last Name" v-model="form_lastName" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_lastName" :message="errors.form_lastName" />
					</div>
					<div class="py-1 w-full">
						<FormControl type="autocomplete" :options="genderOptions" v-model="form_gender" label="Gender" size="sm" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_gender" :message="errors.form_gender" />
					</div>
					<div class="py-1 w-full">
						<DatePicker
							v-model="form_dob"
							variant="subtle"
							placeholder="Date of Birth"
							:disabled="false"
							:required="true"
							label="Date of Birth"
						/>
						<ErrorMessage v-if="errors.form_dob" :message="errors.form_dob" />
					</div>
					<div class="py-1 w-full">
						<FormControl type="select" :options="['Single', 'Married', 'Divorced', 'Widow']" v-model="form_marital" label="Marital Status" size="sm" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_marital" :message="errors.form_marital" />
					</div>
				</div>
			</div>
			<!-- Address & Contact Section -->
			<div>
				<h4 class="py-2 font-semibold text-lg mb-2">Address & Contact</h4>
				<div class="grid grid-cols-2 gap-2">
					<!-- Left Side Fields -->
					<div class="py-1 w-full">
						<FormControl label="Mobile" v-model="form_mobile" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_mobile" :message="errors.form_mobile" />
					</div>
					<div class="py-1 w-full">
						<FormControl label="Address Line 1" v-model="form_addressLine1" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_addressLine1" :message="errors.form_addressLine1" />
					</div>
					<div class="py-1 w-full">
						<FormControl label="City/District" v-model="form_city" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_city" :message="errors.form_city" />
					</div>
					<div class="py-1 w-full">
						<FormControl label="Address Line 2" v-model="form_addressLine2" type="text" size="sm" variant="subtle" :disabled="false" />
						<ErrorMessage v-if="errors.form_addressLine2" :message="errors.form_addressLine2" />
					</div>
					<div class="py-1 w-full">
						<FormControl label="State/Province" v-model="form_state" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_state" :message="errors.form_state" />
					</div>
					<div class="py-1 w-full">
						<FormControl label="ZIP Code" v-model="form_zip" type="text" size="sm" variant="subtle" :disabled="false" :required="true" />
						<ErrorMessage v-if="errors.form_zip" :message="errors.form_zip" />
					</div>
				</div>
			</div>
			<div>
				<ErrorMessage v-if="errors.profile_completion_fail" :message="errors.profile_completion_fail" />
			</div>
		</template>
		<template #actions>
			<Button variant="solid" @click="handleConfirm">Confirm</Button>
		</template>
	</Dialog>
</template>

<script setup>
	import { ref, onMounted, onBeforeUnmount } from "vue";
	import { FormControl, createResource, Dialog, ErrorMessage, DatePicker } from "frappe-ui";
	import { useRouter } from "vue-router";
	import { QrcodeStream } from "vue-qrcode-reader";
	import Footer from '@/components/Footer.vue';
	import BrandLogo from '@/components/BrandLogo.vue';

	const router = useRouter();

	let patient_id = ref("");
	let success_dialog = ref(false);
	let route_dialog = ref(false);
	let qr_dialog = ref(false);
	let alert_dialog = ref(false);
	let paid = ref(true);
	let dialog_message = ref("");
	let dialog_title = ref("");
	let appointment = ref("");
	let practitioner = ref("");
	let dialogPatient = ref(false);
	let patientList = ref([]);
	let selected_patient = ref(null);
	let dialogAppointment = ref(false);
	let appointmentList = ref([]);
	let selectedAppointment = ref(null);
	let appointment_id = ref("");
	let show_qr_camera = ref(false);
	const selectedConstraints = ref({ facingMode: 'environment' });
	const defaultConstraintOptions = [
		{ label: 'rear camera', constraints: { facingMode: 'environment' } },
		{ label: 'front camera', constraints: { facingMode: 'user' } }
	];
	const constraintOptions = ref(defaultConstraintOptions);
	const scannerKey = ref(0);
	let token = ref("");
	const error = ref('');

	let complete_profile_dialog = ref(false);
	let form_firstName = ref("");
	let form_lastName = ref("");
	let form_mobile = ref("");
	let errors = ref({});
	let form_marital = ref("");
	let form_gender = ref("");
	let form_dob = ref(null);
	let form_addressLine1 = ref("");
	let form_addressLine2 = ref("");
	let form_city = ref("");
	let form_state = ref("");
	let form_zip = ref("");
	let genderOptions = ref("");

	let logo = ref("");
	let get_logo = createResource({
		url:"/api/method/marley_frontend.api.get_logo_image",
		method: "GET",
		makeParams() {
			return {};
		},
		onSuccess(response) {
			if (response) {
				logo.value = response;
			}
			else {
				logo.value = "https://raw.githubusercontent.com/frappe/healthcare/develop/healthcare/public/images/healthcare.svg";
			}
		},
	});
	get_logo.fetch();

	const isVerticalScreen = ref(false)

	function checkOrientation() {
		isVerticalScreen.value = window.innerHeight > window.innerWidth
	}

	onMounted(() => {
		checkOrientation()
		window.addEventListener('resize', checkOrientation)
	})

	onBeforeUnmount(() => {
		window.removeEventListener('resize', checkOrientation)
	})

	let genders = createResource({
		url: "/api/method/marley_frontend.api.get_gender",
		method: "GET",
		onSuccess(response) {
			genderOptions.value = response.genders;
		},
		onError(error) {
			dialog_title = "Fetching Gender Failed";
			dialog_message = error.messages?.[0] || error;
			alert_dialog.value = true;
		},
	});
	genders.fetch();

	let get_qr_config = createResource({
		url:"/api/method/marley_frontend.api.get_qr_config",
		method: "GET",
		onSuccess(response) {
			if (response) {
				show_qr_camera.value = response[0] == 0 ? false : true;
			}
		},
	})
	get_qr_config.fetch();

	let check_appointment = createResource({
		url: "/api/method/marley_frontend.api.check_appointment",
		method: "GET",
		makeParams() {
			return {
				patient_id: localStorage.getItem("patient_id"),
				appointment_id: appointment_id ? appointment_id : null
			};
		},
		onSuccess(response) {
			if (response["message"]) {
				dialog_message = `${response["message"]}`;
				dialog_title = "Message";
				token.value = null;
				success_dialog.value = true;
			} else if (response["alert"]) {
				dialog_message = response["alert"];
				dialog_title = "Alert";
				alert_dialog.value = true;
			} else if (response["route"]) {
				paid = false;
				practitioner = response["practitioner"];
				appointment = response["appointment"];
				dialog_message = response["payment_message"];
				dialog_title = "Complete Payment";
				route_dialog.value = true;
			}
		},
		onError(error) {
			dialog_title = "Checking Appointment Failed";
			dialog_message = error.messages?.[0] || error;
			alert_dialog.value = true;
		}
	});

	let get_appointments = createResource({
		url: "/api/method/marley_frontend.api.get_all_appointments",
		method: "GET",
		makeParams() {
			return {
				patient_id: localStorage.getItem("patient_id") || null,
				token: token.value || null
			};
		},
		onSuccess(response) {
			if(response && response["appointment_list"]) {
				// show appointment selection dialog
				appointmentList.value = response["appointment_list"];
				dialogAppointment.value = true;
				// set appointment_id and call api again with it
			} else if(response && response["appointment"]) {
				appointment_id = response["appointment"];
				if (response["patient"]) {
					localStorage.setItem("patient_id", response["patient"]);
				}
				localStorage.setItem("booking_date", response["date"]);
				check_profile_before_checkin(localStorage.getItem("patient_id"));
			} else if(response && response["Error"]){
				dialog_title = "Fetching Appointment Failed";
				dialog_message = response["Error"];
				alert_dialog.value = true
			} else if(response && response["Token Not Exist"]){
				dialog_title = "Token Verification Failed";
				dialog_message = response["Token Not Exist"];
				alert_dialog.value = true;
			}
		},
		onError(error) {
			dialog_title = "Fetching Appointment Failed";
			dialog_message = error.messages?.[0] || error;
			alert_dialog.value = true;
		}
	})

	let patient_verification = createResource({
		url: "/api/method/marley_frontend.api.get_patient",
		method: "GET",
		makeParams() {
			return {
				patient_id: patient_id.value,
			};
		},
		onSuccess(response) {
			if (response["token"]) {
				token.value = response.token;
				get_appointments.fetch();
			}
			else if (response.status === "success" && response.patients.length > 0) {
				patientList.value = response.patients;
				dialogPatient.value = true;
			}
			else if (response["error"]) {
				dialog_message = `${response["error"]}. Please try again with a different number or get registred from registration counter`;
				dialog_title = "Alert";
				alert_dialog.value = true;
			}
		},
		onError(error) {
			dialog_title = "Fetching Patient Failed";
			dialog_message = error.messages?.[0] || error;
			alert_dialog.value = true;
		}
	});

	function check_profile_before_checkin(patient) {
		let check_profile = createResource({
			url: '/api/method/marley_frontend.waitlist.get_current_patient_data',
			method: 'GET',
			makeParams() {
				return {
					patient: patient,
				};
			},
			onSuccess(response) {
				if (!response.profile_completed) {
					form_firstName.value = response. doc.first_name || '';
					form_lastName.value = response.doc.last_name || '';
					form_gender.value = response.doc.sex || '';
					form_mobile.value = response.doc.phone || '';
					form_dob.value = response.doc.dob || '';
					form_addressLine1.value = response.doc.address_line1 || '';
					form_addressLine2.value = response.doc.address_line2 || '';
					form_city.value = response.doc.city || '';
					form_state.value = response.doc.state || '';
					form_zip.value = response.doc.zip_code || '';
					form_marital.value = response.doc.marital_status || '';

					complete_profile_dialog.value = true;
				} else {
					check_appointment.fetch();
				}
			},
			onError(error) {
				dialog_title = "Fetching Profile Failed";
				dialog_message = error.messages?.[0] || error;
				alert_dialog.value = true;
			},
		});
		check_profile.submit();
	}

	const selectPatient = (patientId) => {
		selected_patient.value = patientId;
	};

	const confirmSelection = () => {
		if (selected_patient.value) {
			localStorage.setItem("patient_id", selected_patient.value);
			get_appointments.fetch();
			dialogPatient.value = false;
		}
	};

	const selectAppointment = (appId) => {
		selectedAppointment.value = appId;
	};

	function openQRScanner() {
		dialog_title.value = "Scan QR Code";
		dialog_message = "Please position the QR code within the scanner frame.";
		qr_dialog.value = true;
	}

	async function onCameraReady() {
		try {
			const devices = await navigator.mediaDevices.enumerateDevices();
			const videoDevices = devices.filter(({ kind }) => kind === 'videoinput');

			constraintOptions.value = [
				...defaultConstraintOptions,
				...videoDevices.map(({ deviceId, label }) => ({
					label: `${label} (ID: ${deviceId})`,
					constraints: { deviceId },
				})),
			];

			// Reset error if camera initializes successfully
			error.value = '';
		} catch (err) {
			onError(err);
		}
	};

	function onDetect(detectedCodes) {
		if (detectedCodes.length > 0) {
			token.value = String(detectedCodes[0].rawValue);
			get_appointments.fetch();
			qr_dialog.value = false;

			// Reset the scanner by changing the key
			scannerKey.value++;
		}
	};

	function onError(err) {
		error.value = `[${err.name}]: `

		if (err.name === 'NotAllowedError') {
			error.value += 'you need to grant camera access permission'
		} else if (err.name === 'NotFoundError') {
			error.value += 'no camera on this device'
		} else if (err.name === 'NotSupportedError') {
			error.value += 'secure context required (HTTPS, localhost)'
		} else if (err.name === 'NotReadableError') {
			error.value += 'is the camera already in use?'
		} else if (err.name === 'OverconstrainedError') {
			error.value += 'installed cameras are not suitable'
		} else if (err.name === 'StreamApiNotSupportedError') {
			error.value += 'Stream API is not supported in this browser'
		} else if (err.name === 'InsecureContextError') {
			error.value +=
			'Camera access is only permitted in secure context. Use HTTPS or localhost rather than HTTP.'
		} else {
			error.value += err.message
		}
	};

	onMounted(onCameraReady);

	const confirmAppSelection = () => {
		if (selectedAppointment.value) {
			let selectedAppData = appointmentList.value.find(
				(app) => app.name === selectedAppointment.value
			);
			if (selectedAppData) {
				localStorage.setItem("booking_date", selectedAppData.appointment_date)
				appointment_id = selectedAppointment.value
				check_profile_before_checkin(localStorage.getItem("patient_id"));
			}
			dialogAppointment.value = false;
		}
	};

	const handleConfirm = () => {
		errors.value = {};
		let isValid = true;
		if (!form_marital.value || !form_dob.value || !form_addressLine1.value || !form_city.value || !form_state.value) {
			if (!form_addressLine1.value) {
				errors.value.form_addressLine1 = "This field is required.";
				isValid = false;
			}
			if (!form_city.value) {
				errors.value.form_city = "This field is required.";
				isValid = false;
			}
			if (!form_state.value) {
				errors.value.form_state = "This field is required.";
				isValid = false;
			}
			if (!form_marital.value) {
				errors.value.form_marital = "This field is required.";
				isValid = false;
			}
			if (!form_dob.value) {
				errors.value.form_dob = "This field is required.";
				isValid = false;
			}
			if (!form_mobile.value) {
				errors.value.form_mobile = "This field is required.";
				isValid = false;
			}
			// if (!form_addressLine2.value) {
			// 	errors.value.form_addressLine2 = "This field is required.";
			// 	isValid = false;
			// }
			if (!form_lastName.value) {
				errors.value.form_lastName = "This field is required.";
				isValid = false;
			}
			if (!form_zip.value) {
				errors.value.form_zip = "This field is required.";
				isValid = false;
			}
		} else {
			updateDetails.submit();
		}
	};

	// update patient details before booking
	let updateDetails = createResource({
		url: "/api/method/marley_frontend.waitlist.update_patient",
		method: "POST",
		makeParams() {
			return {
				patient: localStorage.getItem("patient_id"),
				firstname: form_firstName.value,
				lastname: form_lastName.value,
				mobile: form_mobile.value,
				gender: form_gender.value,
				dob: form_dob.value,
				address1: form_addressLine1.value,
				address2: form_addressLine2.value,
				city: form_city.value,
				state: form_state.value,
				zip: form_zip.value,
				marital: form_marital.value
			}
		},
		onSuccess(response) {
			complete_profile_dialog.value = false;
			check_appointment.fetch();
		},
		onError(error) {
			dialog_title = "Updating Patient Failed";
			dialog_message = error.messages?.[0] || error;
			alert_dialog.value = true;
		}
	});

	function handleButtonClick() {
		patient_verification.fetch();
	};

	function onCheckin() {
		if (paid) {
			route_dialog.value = false;
			localStorage.clear();
			router.push({ name: "Checkin" });
		} else {
			router.push({
				name: "Payment",
				query: {
					practitioner: practitioner,
					appointment: appointment,
					from_checkin: true
				}
			});
		}
	};
</script>